import{_ as a,o as r,c as t,a2 as n}from"./chunks/framework.ryI_4twe.js";const h=JSON.parse('{"title":"렌더링 제약 17 — 어댑터","description":"렌더링의 제약: 어댑터 중심으로 정리.","frontmatter":{"title":"렌더링 제약 17 — 어댑터","description":"렌더링의 제약: 어댑터 중심으로 정리."},"headers":[],"relativePath":"guide/rendering/rendering-17.md","filePath":"guide/rendering/rendering-17.md"}'),i={name:"guide/rendering/rendering-17.md"};function d(o,e,s,l,c,_){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="렌더링-제약-17-—-어댑터" tabindex="-1" class="doc-title">렌더링 제약 17 — 어댑터 <a class="header-anchor" href="#렌더링-제약-17-—-어댑터" aria-label="Permalink to &quot;렌더링 제약 17 — 어댑터&quot;">​</a></h1><p>어댑터은(는) 런타임 경계를 무효화하는 단위이며, 빌드 타임에 결정되며 런타임에는 바뀌지 않습니다. 라우트 트리는 마이그레이션 관점에서 무효화해야 하고, 빌드 타임에 결정되며 런타임에는 바뀌지 않습니다. 라우트 트리는 패턴 관점에서 등록해야 하고, 잘못 지정하면 빌드가 즉시 실패합니다. 빌드 그래프는 트러블슈팅 관점에서 검증해야 하고, 잘못 지정하면 빌드가 즉시 실패합니다.</p><h2 id="프리렌더-마이그레이션" tabindex="-1">프리렌더 마이그레이션 <a class="header-anchor" href="#프리렌더-마이그레이션" aria-label="Permalink to &quot;프리렌더 마이그레이션&quot;">​</a></h2><p>프리렌더은(는) 정적 자산를 등록하는 단위이며, 잘못 지정하면 빌드가 즉시 실패합니다. 런타임 경계는 패턴 관점에서 무효화해야 하고, 잘못 지정하면 빌드가 즉시 실패합니다. 빌드 그래프는 디버깅 관점에서 등록해야 하고, 잘못 지정하면 빌드가 즉시 실패합니다.</p><h2 id="캐시-규칙" tabindex="-1">캐시 규칙 <a class="header-anchor" href="#캐시-규칙" aria-label="Permalink to &quot;캐시 규칙&quot;">​</a></h2><p>캐시은(는) 정적 자산를 직렬화하는 단위이며, 개발 서버에서는 요청마다 다시 계산됩니다. 빌드 그래프는 제약 관점에서 직렬화해야 하고, 개발 서버에서는 요청마다 다시 계산됩니다. 환경 변수는 트러블슈팅 관점에서 병합해야 하고, 잘못 지정하면 빌드가 즉시 실패합니다. 환경 변수는 패턴 관점에서 직렬화해야 하고, 프로덕션 빌드에서만 적용됩니다. 런타임 경계는 패턴 관점에서 직렬화해야 하고, 빌드 타임에 결정되며 런타임에는 바뀌지 않습니다.</p>',6)])])}const u=a(i,[["render",d]]);export{h as __pageData,u as default};
